-- 96 fiches minéraux supplémentaires : variétés à part entière (rubis, émeraude, aigue-marine…), minéraux d'uranium et espèces voisines.
-- Une fiche déjà présente (même nom ou même slug) n'est pas modifiée.
on conflict do nothing;

-- Saphir : fiche existante créée avec son seul nom ; seuls les champs vides sont complétés.
update public.minerals set
  formula = coalesce(formula, 'Al₂O₃'),
  crystal_system = coalesce(crystal_system, 'Trigonal'),
  chemical_class = coalesce(chemical_class, 'Oxydes et hydroxydes'),
  hardness = coalesce(hardness, 9),
  hardness_max = coalesce(hardness_max, 9),
  density = coalesce(density, 3.95),
  density_max = coalesce(density_max, 4.1),
  colors = coalesce(colors, array['bleu','bleu roi','jaune','rose','vert','incolore']::text[]),
  luster = coalesce(luster, 'adamantin à vitreux'),
  cleavage = coalesce(cleavage, 'aucun (plans de séparation)'),
  streak = coalesce(streak, 'blanc'),
  transparency = coalesce(transparency, 'transparent à opaque'),
  fracture = coalesce(fracture, 'conchoïdale à irrégulière'),
  fluorescence = coalesce(fluorescence, 'Variable : souvent inerte (bleu), orangé à rouge pour les saphirs roses et orangés.'),
  habit = coalesce(habit, 'Cristaux en tonnelets et bipyramides hexagonales, souvent zonés de bandes de couleur.'),
  formation = coalesce(formation, 'Basaltes alcalins et leurs alluvions (Australie, Thaïlande ; Expailly et Riou Pézouliou en Haute-Loire), marbres et pegmatites (Cachemire, Sri Lanka, Madagascar).'),
  etymology = coalesce(etymology, 'Du latin sapphirus, du grec sappheiros (pierre bleue).'),
  varieties = coalesce(varieties, 'Saphir bleu, saphirs « de couleur » (jaune, rose, vert…), padparadscha (rose orangé), saphir étoilé (astérisme). Toutes les couleurs de corindon sauf le rouge (rubis).'),
  confusions = coalesce(confusions, 'Spinelle bleu et iolite : plus tendres. Tanzanite : bien plus tendre. Verre : bulles, plus léger.'),
  description = coalesce(description, 'Corindon de toutes les couleurs sauf le rouge, coloré en bleu par le fer et le titane ; deuxième minéral le plus dur après le diamant. Le Velay en a livré dans ses basaltes.')
where slug = 'saphir';
