insert into public.minerals (name, slug, formula, crystal_system, chemical_class, hardness, hardness_max, density, density_max, colors, luster, cleavage, streak, transparency, fracture, fluorescence, habit, formation, etymology, varieties, confusions, description, publication_status) values
  ('Rubis', 'rubis', 'Al₂O₃', 'Trigonal', 'Oxydes et hydroxydes', 9, 9, 3.95, 4.1, array['rouge','rouge pourpre','rouge rosé']::text[], 'adamantin à vitreux', 'aucun (plans de séparation)', 'blanc', 'transparent à opaque', 'conchoïdale à irrégulière', 'Rouge vif aux UV longs (chrome).', 'Prismes et tonnelets hexagonaux, tablettes.', 'Marbres métamorphiques (Myanmar, Vietnam), amphibolites, basaltes et leurs alluvions (Thaïlande, Mozambique).', 'Du latin ruber (rouge).', 'Rubis étoilé (astérisme). Variété rouge du corindon, colorée par le chrome.', 'Spinelle rouge : cubique, sans dichroïsme. Grenat pyrope : pas de fluorescence rouge.', 'Corindon rouge coloré par le chrome, l''une des quatre pierres précieuses ; sa fluorescence rouge avive sa couleur à la lumière du jour.', 'published'),
  ('Padparadscha', 'padparadscha', 'Al₂O₃', 'Trigonal', 'Oxydes et hydroxydes', 9, 9, 3.95, 4.1, array['rose orangé','orange saumon']::text[], 'adamantin à vitreux', 'aucun (plans de séparation)', 'blanc', 'transparent à opaque', 'conchoïdale à irrégulière', 'Orangé à rouge aux UV longs.', 'Prismes et tonnelets hexagonaux, tablettes.', 'Alluvions gemmifères du Sri Lanka, Madagascar, Tanzanie.', 'Du cinghalais padmaraga (couleur de la fleur de lotus).', 'Variété rose orangé du saphir.', 'Saphir orange ou rose : la teinte doit mêler les deux. Spinelle : cubique.', 'Saphir rose orangé « couleur coucher de soleil », l''une des variétés de corindon les plus rares.', 'published'),
  ('Aigue-marine', 'aigue-marine', 'Be₃Al₂Si₆O₁₈', 'Hexagonal', 'Silicates (cyclosilicates)', 7.5, 8, 2.65, 2.8, array['bleu ciel','bleu vert','bleu profond']::text[], 'vitreux', 'imparfait (basal)', 'blanc', 'transparent à translucide', 'conchoïdale à irrégulière', null, 'Prismes hexagonaux allongés, striés en long.', 'Pegmatites granitiques et leurs alluvions (Brésil, Madagascar, Pakistan, Nigeria).', 'Du latin aqua marina (eau de mer).', 'Variété bleue du béryl, colorée par le fer ; « Santa Maria » (bleu intense).', 'Topaze bleue : clivage basal parfait, plus dense. Euclase : clivage parfait.', 'Béryl bleu des pegmatites, aux longs prismes limpides couleur d''eau de mer.', 'published'),
  ('Émeraude', 'emeraude', 'Be₃Al₂Si₆O₁₈', 'Hexagonal', 'Silicates (cyclosilicates)', 7.5, 8, 2.65, 2.8, array['vert','vert bleuté','vert intense']::text[], 'vitreux', 'imparfait (basal)', 'blanc', 'transparent à translucide', 'conchoïdale à irrégulière', 'Parfois rouge faible (chrome).', 'Prismes hexagonaux allongés, striés en long.', 'Filons hydrothermaux dans des schistes noirs (Colombie), micaschistes au contact de pegmatites (Brésil, Zambie, Oural).', 'Du grec smaragdos, par le latin.', 'Variété verte du béryl, colorée par le chrome ou le vanadium ; émeraude trapiche (Colombie).', 'Béryl vert : coloré par le fer, teinte plus pâle. Tsavorite et démantoïde : cubiques, sans prismes.', 'Béryl vert intense coloré par le chrome, pierre précieuse dont les inclusions forment le « jardin ».', 'published'),
  ('Morganite', 'morganite', 'Be₃Al₂Si₆O₁₈', 'Hexagonal', 'Silicates (cyclosilicates)', 7.5, 8, 2.65, 2.8, array['rose pêche','rose saumon','violet rosé']::text[], 'vitreux', 'imparfait (basal)', 'blanc', 'transparent à translucide', 'conchoïdale à irrégulière', null, 'Prismes hexagonaux allongés, striés en long.', 'Pegmatites à lithium (Madagascar, Brésil, Californie).', 'De John Pierpont Morgan (1837-1913), banquier et collectionneur américain.', 'Variété rose du béryl, colorée par le manganèse.', 'Kunzite : clivage parfait, fluorescente. Topaze rose : plus dense.', 'Béryl rose des pegmatites à lithium, souvent en prismes courts et larges.', 'published'),
  ('Héliodore', 'heliodore', 'Be₃Al₂Si₆O₁₈', 'Hexagonal', 'Silicates (cyclosilicates)', 7.5, 8, 2.65, 2.8, array['jaune doré','jaune vert']::text[], 'vitreux', 'imparfait (basal)', 'blanc', 'transparent à translucide', 'conchoïdale à irrégulière', null, 'Prismes hexagonaux allongés, striés en long.', 'Pegmatites granitiques (Ukraine, Brésil, Namibie).', 'Du grec hêlios (soleil) et dôron (don).', 'Variété jaune du béryl, colorée par le fer ferrique.', 'Citrine : sans prismes hexagonaux. Chrysobéryl : plus dur et plus dense.', 'Béryl jaune doré, le « don du soleil », en prismes limpides des pegmatites.', 'published'),
  ('Goshénite', 'goshenite', 'Be₃Al₂Si₆O₁₈', 'Hexagonal', 'Silicates (cyclosilicates)', 7.5, 8, 2.65, 2.8, array['incolore','blanc']::text[], 'vitreux', 'imparfait (basal)', 'blanc', 'transparent à translucide', 'conchoïdale à irrégulière', null, 'Prismes hexagonaux allongés, striés en long.', 'Pegmatites granitiques (Brésil, Madagascar).', 'De Goshen (Massachusetts, États-Unis).', 'Variété incolore du béryl.', 'Quartz : sans prismes à base plane, plus léger. Phénakite : plus dure.', 'Béryl incolore, autrefois taillé pour imiter le diamant ou servir de verre de lunettes.', 'published'),
  ('Bixbite', 'bixbite', 'Be₃Al₂Si₆O₁₈', 'Hexagonal', 'Silicates (cyclosilicates)', 7.5, 8, 2.65, 2.8, array['rouge framboise','rouge groseille']::text[], 'vitreux', 'imparfait (basal)', 'blanc', 'transparent à translucide', 'conchoïdale à irrégulière', null, 'Prismes hexagonaux allongés, striés en long.', 'Cavités de rhyolites à topaze (Wah Wah Mountains, Utah).', 'De Maynard Bixby (1853-1935), prospecteur de l''Utah.', 'Béryl rouge, coloré par le manganèse ; aussi appelé « émeraude rouge ».', 'Rubis : bien plus dur. Rubellite : prismes striés à section triangulaire.', 'Béryl rouge, l''une des gemmes les plus rares au monde, presque seulement connu dans l''Utah.', 'published'),
  ('Citrine', 'citrine', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 7, 7, 2.65, 2.65, array['jaune','jaune doré','orange']::text[], 'vitreux', 'aucun', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Prismes hexagonaux terminés par des rhomboèdres, faces striées.', 'Pegmatites et géodes ; la plupart des citrines du commerce sont des améthystes chauffées (Brésil).', 'Du latin citrus (citron).', 'Variété jaune du quartz.', 'Topaze : clivage parfait, plus dense. Héliodore : prismes hexagonaux à base plane.', 'Quartz jaune ; naturelle, elle est rare et pâle, chauffée (améthyste), elle tire sur l''orange.', 'published'),
  ('Quartz fumé', 'quartz-fume', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 7, 7, 2.65, 2.65, array['brun clair','brun fumé','gris brun']::text[], 'vitreux', 'aucun', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Prismes hexagonaux terminés par des rhomboèdres, faces striées.', 'Fentes alpines (massif du Mont-Blanc), granites et pegmatites.', 'De sa teinte enfumée.', 'Variété brune du quartz, colorée par irradiation naturelle de l''aluminium ; morion (noir), cairngorm (Écosse).', 'Topaze brune : clivage parfait. Axinite : cristaux en coin tranchants.', 'Quartz brun des fentes alpines, coloré par la radioactivité naturelle des roches encaissantes.', 'published'),
  ('Morion', 'morion', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 7, 7, 2.65, 2.65, array['noir','brun très foncé']::text[], 'vitreux', 'aucun', 'blanc', 'opaque à translucide sur les bords', 'conchoïdale', null, 'Prismes hexagonaux terminés par des rhomboèdres, faces striées.', 'Granites et pegmatites, fentes alpines.', 'Du latin mormorion, nom d''une pierre noire chez Pline.', 'Variété noire et opaque du quartz fumé.', 'Tourmaline schorl : prismes striés à section triangulaire. Obsidienne : amorphe.', 'Quartz fumé si sombre qu''il paraît noir et opaque.', 'published'),
  ('Quartz rose', 'quartz-rose', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 7, 7, 2.65, 2.65, array['rose pâle','rose']::text[], 'vitreux', 'aucun', 'blanc', 'translucide', 'conchoïdale', null, 'Masses compactes ; cristaux très rares (Brésil).', 'Cœur des pegmatites granitiques (Madagascar, Brésil).', 'De sa couleur.', 'Variété rose du quartz ; quartz rose astérié.', 'Rhodonite et rhodochrosite : plus denses, plus tendres. Morganite : prismes hexagonaux.', 'Quartz rose laiteux des pegmatites, coloré par d''infimes fibres minérales ; les vrais cristaux sont rarissimes.', 'published'),
  ('Cristal de roche', 'cristal-de-roche', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 7, 7, 2.65, 2.65, array['incolore']::text[], 'vitreux', 'aucun', 'blanc', 'transparent', 'conchoïdale', null, 'Prismes hexagonaux terminés par des rhomboèdres, faces striées.', 'Fentes alpines (Oisans, Mont-Blanc), filons hydrothermaux.', 'Du grec krystallos (glace) : on le croyait de la glace éternelle.', 'Variété incolore et limpide du quartz.', 'Verre : bulles, plus tendre, tiède au toucher. Calcite : clivage, effervescence.', 'Quartz parfaitement limpide, que les Anciens prenaient pour une glace devenue pierre.', 'published'),
  ('Aventurine', 'aventurine', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 7, 7, 2.65, 2.65, array['vert','bleu vert','brun orangé']::text[], 'vitreux, scintillant', 'aucun', 'blanc', 'translucide à opaque', 'irrégulière', null, 'Masses grenues (quartzite) parsemées de paillettes scintillantes.', 'Quartzites métamorphiques à fuchsite (Inde, Brésil).', 'De l''italien avventura (hasard), d''après un verre pailleté obtenu par accident.', 'Quartz à paillettes de fuchsite verte (aventurescence).', 'Amazonite : clivage, feldspath. Verre aventurine : paillettes de cuivre régulières.', 'Quartzite verte scintillante grâce à ses paillettes de mica chromifère.', 'published'),
  ('Œil-de-tigre', 'oeil-de-tigre', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 7, 7, 2.65, 2.65, array['jaune doré','brun']::text[], 'soyeux', 'aucun', 'blanc', 'opaque', 'esquilleuse', null, 'Plaquettes fibreuses ; poli en cabochon, il montre un reflet mobile (chatoyance).', 'Quartz remplaçant des fibres de crocidolite (Griqualand, Afrique du Sud).', 'De son reflet mobile, comme un œil de félin.', 'Œil-de-faucon (bleu, crocidolite non altérée), œil-de-taureau (rouge, chauffé).', 'Œil-de-chat (chrysobéryl) : plus dur, translucide.', 'Quartz fibreux chatoyant né du remplacement d''un amiante bleu, la crocidolite.', 'published'),
  ('Agate', 'agate', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 6.5, 7, 2.58, 2.64, array['gris bleu','blanc','rouge','brun','multicolore']::text[], 'cireux à vitreux', 'aucun', 'blanc', 'translucide à opaque', 'conchoïdale', null, 'Nodules et géodes à bandes concentriques.', 'Cavités de laves (Brésil, Uruguay) et rognons dans les sédiments.', 'Du fleuve Achatès, en Sicile.', 'Calcédoine rubanée ; agate dendritique, agate mousse, agate de feu.', 'Onyx : bandes parallèles noires et blanches. Jaspe : opaque, sans rubans translucides.', 'Calcédoine à bandes concentriques colorées, formée couche après couche dans les cavités des roches.', 'published'),
  ('Onyx', 'onyx', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 6.5, 7, 2.58, 2.64, array['noir','blanc']::text[], 'cireux à vitreux', 'aucun', 'blanc', 'translucide à opaque', 'conchoïdale', null, 'Plaques à bandes parallèles noires et blanches.', 'Cavités de laves et filons (Brésil, Inde).', 'Du grec onyx (ongle).', 'Agate à bandes parallèles ; sardonyx (bandes brun rouge).', 'Onyx marbre : calcite rubanée, plus tendre, effervescente.', 'Agate à bandes noires et blanches parallèles, taillée en camées depuis l''Antiquité.', 'published'),
  ('Cornaline', 'cornaline', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 6.5, 7, 2.58, 2.64, array['orange','rouge orangé','brun rouge']::text[], 'cireux à vitreux', 'aucun', 'blanc', 'translucide', 'conchoïdale', null, 'Masses compactes, galets.', 'Laves et alluvions (Inde, Brésil).', 'Du latin cornum (cornouille), fruit rouge.', 'Calcédoine orange rouge colorée par des oxydes de fer ; sardoine (brune).', 'Jaspe rouge : opaque. Verre teinté : bulles.', 'Calcédoine orange translucide, colorée par le fer, gravée en sceaux dès l''Antiquité.', 'published'),
  ('Chrysoprase', 'chrysoprase', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 6.5, 7, 2.58, 2.64, array['vert pomme']::text[], 'cireux à vitreux', 'aucun', 'blanc', 'translucide', 'conchoïdale', null, 'Veines et masses compactes.', 'Altération de roches ultrabasiques riches en nickel (Queensland, Australie).', 'Du grec chrysos (or) et prason (poireau).', 'Calcédoine vert pomme colorée par le nickel.', 'Jade jadéite : plus dense. Variscite : plus tendre.', 'Calcédoine vert pomme colorée par le nickel, la plus prisée des calcédoines.', 'published'),
  ('Jaspe', 'jaspe', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 6.5, 7, 2.58, 2.64, array['rouge','brun','jaune','vert']::text[], 'terne à cireux', 'aucun', 'blanc', 'opaque', 'conchoïdale', null, 'Masses compactes, galets, bancs.', 'Silicifications de sédiments ou de cendres volcaniques, filons.', 'Du grec iaspis.', 'Quartz microgrenu riche en impuretés ; jaspe paysage, jaspe océan, héliotrope.', 'Agate : translucide, rubanée. Chert : gris, plus homogène.', 'Silice microcristalline opaque, colorée par 20 % d''impuretés ou plus, souvent en motifs paysagers.', 'published'),
  ('Héliotrope', 'heliotrope', 'SiO₂', 'Trigonal', 'Oxydes et hydroxydes', 6.5, 7, 2.58, 2.64, array['vert foncé à taches rouges']::text[], 'cireux à vitreux', 'aucun', 'blanc', 'opaque à translucide', 'conchoïdale', null, 'Masses compactes.', 'Laves et filons (Inde).', 'Du grec hêlios (soleil) et trepein (tourner).', 'Calcédoine verte ponctuée de rouge, dite « jaspe sanguin ».', 'Jaspe vert : sans points rouges.', 'Calcédoine vert sombre semée de taches rouges, la « pierre de sang » des anciens lapidaires.', 'published'),
  ('Alexandrite', 'alexandrite', 'BeAl₂O₄', 'Orthorhombique', 'Oxydes et hydroxydes', 8.5, 8.5, 3.7, 3.8, array['vert (lumière du jour)','rouge (lumière artificielle)']::text[], 'vitreux', 'distinct', 'blanc', 'transparent à translucide', 'conchoïdale', 'Rouge faible (chrome).', 'Macles cycliques pseudo-hexagonales (« trillings »).', 'Micaschistes à émeraude (Oural), alluvions (Sri Lanka, Brésil).', 'Du tsar Alexandre II de Russie.', 'Variété de chrysobéryl qui change de couleur selon l''éclairage.', 'Saphir et grenat à changement de couleur : analyse optique.', 'Chrysobéryl chromifère vert à la lumière du jour, rouge à la lumière d''une lampe.', 'published'),
  ('Cymophane', 'cymophane', 'BeAl₂O₄', 'Orthorhombique', 'Oxydes et hydroxydes', 8.5, 8.5, 3.7, 3.8, array['jaune miel','vert jaune']::text[], 'vitreux, soyeux en cabochon', 'distinct', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Cristaux tabulaires ; taillé en cabochon, il montre une ligne lumineuse.', 'Pegmatites et alluvions (Sri Lanka, Brésil).', 'Du grec kyma (vague) et phainein (paraître).', 'Chrysobéryl œil-de-chat (chatoyance).', 'Œil-de-tigre : quartz, bien plus tendre.', 'Chrysobéryl chatoyant, le véritable « œil-de-chat » des joailliers.', 'published'),
  ('Kunzite', 'kunzite', 'LiAlSi₂O₆', 'Monoclinique', 'Silicates (inosilicates)', 6.5, 7, 3.1, 3.2, array['rose','violet rosé']::text[], 'vitreux', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière', 'Orange rosé aux UV ; phosphorescente.', 'Prismes aplatis striés, aux terminaisons corrodées.', 'Pegmatites à lithium (Afghanistan, Brésil, Californie, Madagascar).', 'De George Frederick Kunz (1856-1932), gemmologue américain.', 'Variété rose du spodumène, colorée par le manganèse ; pâlit à la lumière.', 'Morganite : prismes hexagonaux. Améthyste : sans clivage.', 'Spodumène rose violacé, fortement pléochroïque, dont la couleur pâlit au soleil.', 'published'),
  ('Hiddénite', 'hiddenite', 'LiAlSi₂O₆', 'Monoclinique', 'Silicates (inosilicates)', 6.5, 7, 3.1, 3.2, array['vert','vert jaune']::text[], 'vitreux', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière', null, 'Prismes aplatis striés, aux terminaisons corrodées.', 'Pegmatites à lithium (Afghanistan, Brésil, Californie, Madagascar).', 'De William Earl Hidden (1853-1918), minéralogiste américain.', 'Variété verte du spodumène, colorée par le chrome.', 'Émeraude : prismes hexagonaux. Diopside chromifère : plus dense.', 'Spodumène vert, rare, découvert en Caroline du Nord.', 'published'),
  ('Tanzanite', 'tanzanite', 'Ca₂Al₃(SiO₄)(Si₂O₇)O(OH)', 'Orthorhombique', 'Silicates (sorosilicates)', 6, 7, 3.15, 3.4, array['bleu violet','violet','brun (non chauffée)']::text[], 'vitreux', 'parfait', 'blanc', 'transparent à translucide', 'irrégulière à conchoïdale', null, 'Prismes striés ; fort trichroïsme (bleu, violet, brun).', 'Gisement unique de Merelani (Tanzanie), dans des gneiss graphiteux.', 'De la Tanzanie.', 'Variété bleu violet de la zoïsite, colorée par le vanadium ; souvent chauffée.', 'Saphir : bien plus dur. Iolite : plus légère.', 'Zoïsite bleu violet connue d''un seul gisement au monde, au pied du Kilimandjaro.', 'published'),
  ('Péridot', 'peridot', '(Mg,Fe)₂SiO₄', 'Orthorhombique', 'Silicates (nésosilicates)', 6.5, 7, 3.27, 3.37, array['vert olive','vert jaune']::text[], 'vitreux', 'imparfait', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Grains, nodules et prismes trapus.', 'Basaltes et péridotites (Arizona, Pakistan, île de Zabargad) ; grains verts des bombes volcaniques d''Auvergne.', 'Origine discutée, peut-être de l''arabe faridat (gemme).', 'Olivine de qualité gemme ; chrysolite (ancien nom).', 'Prasiolite : plus légère. Diopside : clivage net.', 'Olivine vert olive de qualité gemme ; on en trouve des grains dans les bombes volcaniques du Massif central.', 'published'),
  ('Forstérite', 'forsterite', 'Mg₂SiO₄', 'Orthorhombique', 'Silicates (nésosilicates)', 6.5, 7, 3.2, 3.3, array['incolore','vert pâle','jaune']::text[], 'vitreux', 'imparfait', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Grains, nodules et prismes trapus.', 'Péridotites, marbres magnésiens, météorites.', 'D''Adolarius Jacob Forster (1739-1806), collectionneur anglais.', null, 'Fayalite : pôle ferreux, plus sombre et plus dense.', 'Pôle magnésien de l''olivine, abondante dans le manteau terrestre.', 'published'),
  ('Fayalite', 'fayalite', 'Fe₂SiO₄', 'Orthorhombique', 'Silicates (nésosilicates)', 6.5, 7, 4.3, 4.4, array['brun','noir verdâtre','jaune ambré']::text[], 'vitreux', 'imparfait', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Grains, nodules et prismes trapus.', 'Rhyolites et obsidiennes, scories, granites ferrifères.', 'De l''île de Faial (Açores).', null, 'Forstérite : plus claire et plus légère.', 'Pôle ferreux de l''olivine, présent dans les laves acides et certaines scories.', 'published'),
  ('Opale noble', 'opale-noble', 'SiO₂·nH₂O', 'Amorphe', 'Oxydes et hydroxydes', 5.5, 6.5, 1.9, 2.3, array['blanc laiteux','noir','bleu gris, à reflets multicolores']::text[], 'vitreux à résineux', 'aucun', 'blanc', 'translucide à opaque', 'conchoïdale', null, 'Veines, nodules, remplissages de fossiles.', 'Grès altérés d''Australie (Coober Pedy, Lightning Ridge), laves (Éthiopie, Mexique).', 'Du sanskrit upala (pierre précieuse).', 'Opale à jeux de couleurs : opale noire, opale blanche, opale boulder.', 'Opale synthétique : motifs en « peau de lézard ». Labradorite : clivage.', 'Opale aux jeux de couleurs, nés de minuscules sphères de silice rangées qui diffractent la lumière.', 'published'),
  ('Opale de feu', 'opale-de-feu', 'SiO₂·nH₂O', 'Amorphe', 'Oxydes et hydroxydes', 5.5, 6.5, 1.9, 2.3, array['orange','rouge','jaune']::text[], 'vitreux', 'aucun', 'blanc', 'transparent à translucide', 'conchoïdale', null, 'Nodules dans les rhyolites.', 'Cavités de rhyolites (Querétaro, Mexique).', 'De sa couleur de flamme.', 'Opale orange à rouge, avec ou sans jeux de couleurs.', 'Cornaline : translucide, plus dure. Citrine : cristallisée.', 'Opale transparente orange vif des rhyolites mexicaines.', 'published'),
  ('Amazonite', 'amazonite', 'KAlSi₃O₈', 'Triclinique', 'Silicates (tectosilicates)', 6, 6.5, 2.56, 2.58, array['vert','bleu vert']::text[], 'vitreux', 'parfait', 'blanc', 'translucide à opaque', 'irrégulière', null, 'Prismes trapus, souvent avec quartz fumé.', 'Pegmatites granitiques (Colorado, Madagascar, Russie).', 'Du fleuve Amazone, à tort.', 'Variété verte du microcline, colorée par le plomb.', 'Jade : sans clivage. Turquoise : plus tendre.', 'Microcline vert bleu des pegmatites, souvent associé au quartz fumé dans le Colorado.', 'published'),
